function nav(){const hash=location.hash.slice(1).split('/')[0]||'dashboard',pages=availablePages();const links=pages.map(([id,label,icon])=>`<a href="#${id}" class="${hash===id?'active':''}"><span class="nav-icon">${icon}</span><span>${label}</span></a>`).join('');document.querySelector('#side-nav').innerHTML=links;document.querySelector('#bottom-nav').innerHTML=pages.map(([id,,icon,mobile])=>`<a href="#${id}" class="${hash===id?'active':''}"><span class="nav-icon">${icon}</span><span>${mobile}</span></a>`).join('');}
